using System;using System.IO;using System.Text;using System.Collections;using System.Linq;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using LWS.TruckSports;using LWS.TruckHockey;
namespace LWS.TruckWallball {public sealed class WallballProductionProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
