#endif
 if(run){var g=new GameObject("Owned experimental Wallball opening and sustained volleys");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<WallballProductionProbe>();}}
 WallballMatch m;Keyboard keyboard;string folder,saved;bool had,restored;int errors;readonly StringBuilder log=new StringBuilder();InputSettings.BackgroundBehavior background;
