 keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);yield return SportsProbeScene.Ensure<WallballMatch>("TruckWallball");m=FindAnyObjectByType<WallballMatch>();yield return null;had=SportsPrefs.HasKey(WallballMatch.SetupKey);saved=SportsPrefs.GetString(WallballMatch.SetupKey);Application.logMessageReceived+=Error;m.ChangeSetup();m.blueSize=m.orangeSize=4;m.Configure(WallballMode.AIVsAI);m.players[0].source=HockeySource.Keyboard;Check(m.StartMatch(),"eight-participant first rally starts");float minimum=100;for(int i=0;i<8;i++)for(int j=i+1;j<8;j++)minimum=Mathf.Min(minimum,Vector3.Distance(m.trucks[i].body.position,m.trucks[j].body.position));Check(minimum>3,"all eight spawn centres are distinct with full-truck clearance, min="+minimum);InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return new WaitForSeconds(.2f);var initial=m.trucks[0].body.position;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));float until=Time.realtimeSinceStartup+6,travel=0,motor=0,intent=0;bool released=false,neutralArmed=false;while(Time.realtimeSinceStartup<until&&m.rules.Points==0){travel=Mathf.Max(travel,(m.trucks[0].body.position-initial).magnitude);motor=Math.Max(motor,Math.Abs(m.trucks[0].wheels[0].MotorTorque));intent=Math.Max(intent,m.Drive(0).y);neutralArmed|=m.players[0].released;released|=m.ServeReleased&&!m.trucks[0].body.isKinematic&&m.trucks[0].wheels.All(w=>w.enabled);yield return null;}Check(released&&travel>.8f,"fresh opening input moves the real NWH truck before any point, travel="+travel+" motor="+motor+" intent="+intent+" neutralArmed="+neutralArmed+" serveReleased="+released+" points="+m.rules.Points+" keyboardCurrent="+(Keyboard.current==keyboard));InputSystem.QueueStateEvent(keyboard,new KeyboardState());m.ChangeSetup();m.Configure(WallballMode.AIVsAI);for(int i=0;i<8;i++){m.players[i].difficulty=HockeyDifficulty.Normal;m.players[i].name="Long Wallball Driver "+(i+1);}Check(m.StartMatch(),"autonomous 4v4 match starts");Time.timeScale=4;bool paused=false;int bestVolley=0;float next=0;until=Time.realtimeSinceStartup+360;while(m.rules.Phase!=WallballPhase.Finished&&Time.realtimeSinceStartup<until&&errors<10){bestVolley=Math.Max(bestVolley,m.MaximumVolley);if(!paused&&m.rules.Active&&m.ball.body.linearVelocity.sqrMagnitude>1){m.Pause();var p=m.ball.body.position;var v=m.ball.body.linearVelocity;yield return new WaitForSecondsRealtime(.15f);Check(p==m.ball.body.position&&v==m.ball.body.linearVelocity,"pause preserves actual ball and truck simulation");m.Resume();Time.timeScale=4;paused=true;}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE score="+m.rules.Score[0]+":"+m.rules.Score[1]+" shots="+m.rules.Shots+" returns="+m.PhysicalReturns+" legal="+m.LegalReturns+" maxVolley="+bestVolley);next=Time.realtimeSinceStartup+3;}yield return null;}Check(m.rules.Phase==WallballPhase.Finished&&m.rules.Winner>=0,"real autonomous eight-truck match reaches a locked win-by-two result");Check(m.PhysicalReturns>0&&m.LegalReturns>0,"real eligible contacts produce legal wall returns");Check(bestVolley>=4,"focused sustained volley reaches at least four actual strikes, max="+bestVolley);log.AppendLine("MATCH shots="+m.rules.Shots+" physicalReturns="+m.PhysicalReturns+" legalReturns="+m.LegalReturns+" maxVolley="+bestVolley+" score="+m.rules.Score[0]+":"+m.rules.Score[1]+" neutralReplays="+m.Replays);m.ChangeSetup();m.Configure(WallballMode.AIVsAI);Check(m.StartMatch(),"rematch resets first-rally physical release");Time.timeScale=1;yield return new WaitForSeconds(2.3f);m.Pause();m.menus.Show(WallballScreen.Play);yield return new WaitForSecondsRealtime(.2f);var camera=FindAnyObjectByType<WallballPresentation>().cameraTarget;foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1440,900),new Vector2Int(1280,960),new Vector2Int(2560,1080)}){SportsControlledCapture.Save(m.menus.GetComponent<Canvas>(),new[]{camera},size.x,size.y,folder+"/eight-trucks-"+size.x+"x"+size.y+"-controlled-ui.png");yield return null;}m.ChangeSetup();SportsNavigation.FrontEnd();yield return null;yield return null;var front=FindAnyObjectByType<SportsFrontEnd>();Check(front.pages[1].GetComponentsInChildren<SportsMenuAction>(true).All(a=>a.action!="wallball")&&front.pages[4].GetComponentsInChildren<SportsMenuAction>(true).Count(a=>a.action=="wallball")==1,"Wallball is manually available only in Experimental Scrap Heap");front.Action("scrapheap");Check(front.Page==4,"experimental submenu opens");Restore();log.AppendLine("ERRORS="+errors+". Labelled spawn fixture, injected keyboard opening and actual NWH/PhysX 4v4 match/volleys, controlled UI captures. Experimental; no human/hardware or normal-window/performance claim.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null&&m.menus!=null)m.ChangeSetup();if(had)SportsPrefs.SetString(WallballMatch.SetupKey,saved);else SportsPrefs.DeleteKey(WallballMatch.SetupKey);SportsPrefs.Save();if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings.backgroundBehavior=background;
#if UNITY_EDITOR
 InputSystem.settings.editorInputBehaviorInPlayMode=editorInput;
